__global__ void matrix_mul_kernel(const float* A, const float* B, float* C, int N) {
    __shared__ float As[16][16];
    __shared__ float Bs[16][16];

    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;
    float sum = 0.0f;

    for (int tile = 0; tile < (N + 15) / 16; ++tile) {
        int tile_col = tile * 16 + threadIdx.x;
        int tile_row = tile * 16 + threadIdx.y;

        if (row < N && tile_col < N) {
            As[threadIdx.y][threadIdx.x] = A[row * N + tile_col];
        } else {
            As[threadIdx.y][threadIdx.x] = 0.0f;
        }

        if (tile_row < N && col < N) {
            Bs[threadIdx.y][threadIdx.x] = B[tile_row * N + col];
        } else {
            Bs[threadIdx.y][threadIdx.x] = 0.0f;
        }

        __syncthreads();

        for (int k = 0; k < 16; ++k) {
            sum += As[threadIdx.y][k] * Bs[k][threadIdx.x];
        }

        __syncthreads();
